from bs4 import BeautifulSoup
from markdownify import markdownify
import random
import re
from xml.sax.saxutils import escape
import tiktoken
import urllib.parse

encoding = tiktoken.encoding_for_model("gpt-3.5-turbo")
note_pattern = re.compile(r"{%\s*include.*?%}", flags=re.DOTALL)
highlight_pattern = re.compile(r"{%\s*.*?\s%}", flags=re.DOTALL)


def what_language(el):
    z = re.match(r"{%\s*highlight\s*(\w+)\s%}", el.text)
    if z:
        lang =  z.group(1)
        return lang
    if el.text.find("curl") > 0:
        return "bash"
    if el.text.find("import com.yahoo") > 0:
        return "java"
    return ""

def remove_jekyll(text):
    text = note_pattern.sub("", text)
    text = highlight_pattern.sub("", text)
    return text

def xml_fixup(text):
    regex = r"{%\s*highlight xml\s*%}(.*?){%\s*endhighlight\s*%}"
    matches = re.findall(regex, text, re.DOTALL)
    for match in matches:
        escaped_match = escape(match)
        text = text.replace(match,escaped_match)
    return text

def create_text_doc(doc, paragraph, paragraph_id, header):
    id = doc['put']
    #id:open:doc::open/en/access-logging.html#
    _,namespace,doc_type,_,id = id.split(":")
    #print("n={},doc_type={},id={}".format(namespace,doc_type,id))

    new_namespace = namespace + "-p"
    id = "id:{}:{}::{}".format(new_namespace, "paragraph", id)
    fields = doc['fields']
    n_tokens = len(encoding.encode(paragraph))
    new_doc = {
        "put": id,
        "fields": {
            "title": fields['title'],
            "path": fields['path'],
            "doc_id": fields['path'],
            "namespace": new_namespace,
            "content": paragraph,
            "content_tokens": n_tokens,
            "base_uri": sys.argv[2]
        }
    }

    if header:
        title = fields['title']
        new_title = title + " - " + header
        new_doc["fields"]["title"] = new_title

    if paragraph_id is None:
        paragraph_id = str(random.randint(0,1000))

    new_doc['fields']['path'] = new_doc['fields']['path'] + "#" + paragraph_id
    new_doc['put'] = new_doc['put'] + "-" + urllib.parse.quote(paragraph_id)

    return new_doc


def split_text(soup):
    split_tables(soup)
    split_lists(soup)
    md = markdownify(str(soup), heading_style='ATX', code_language_callback=what_language, strip=['img'])
    lines = md.split("\n")
    header = ""
    text = ""
    id = ""
    data = []
    for line in lines:
        if line.startswith("#"):
            if text:
                data.append((id, header, text))
                text = ""
            header = line.lstrip("#")
            id = "-".join(header.split()).lower()
        else:
            text = text + "\n" + line

    data.append((id, header, text)) #Flush any last data
    return data


def remove_notext_tags(soup):
    for remove_tag in soup.find_all(['style']):
        remove_tag.decompose()


def split_lists(soup):
    for list in soup.body.find_all(['ul', 'ol']):
        for list_item in list.find_all('li'):
            move_linkable_item_to_single_entity(soup, list_item)


def split_tables(soup):
    top_level_tables = soup.body.find_all('table', recursive=False)  # i.e., do not find rows in tables within tables
    for table in top_level_tables:
        tbody = table.find('tbody')  # tbody is implicit and always there
        for row in tbody.find_all('tr', recursive=False):
            move_linkable_item_to_single_entity(soup, row)


def table_header_row(row):
    thead = row.find_parent('table').find('thead')
    if thead is not None:
        return thead.find('tr')
    return None


def move_linkable_item_to_single_entity(soup, item):
    id_elem = item.find('p', {'id': True})

import sys
import re
import json


def read_json_file(file_path):
    data = None
    with open(file_path, "r") as f:
        data = json.load(f)
    return data

def get_phrases(terms):
    # from "learning to rank" to ['learning to rank', 'to rank', 'rank']
    phrases = []
    phrases.append(terms)
    end = terms.find(' ')
    while end != -1:
        start = end+1
        remainder = terms[start:]
        phrases.append(remainder)
        end = terms.find(' ', start)
    return phrases

def write_json_file(terms, file_path):
    feed_list = [
        {
            "update": f'id:term:term::{re.sub(r" ", "/", term)}',
            "create": True,
            "fields": {
                "term": {"assign": data["term"]},
                "terms": {"assign": get_phrases(data["term"])},
                "corpus_count": {"assign": data["count"]},
                "document_count": {"assign": data["docs"]},
            },
        }
        for (term, data) in terms.items()
    ]
    with open(file_path, "w") as f:
        json.dump(feed_list, f, indent=2)


def read_common_words(file_path):
    common_words = set()
    with open(file_path, "r") as f:
        lines = f.readlines()
        for line in lines:
            common_words.add(line.strip())
    return common_words


def clean_text(text):
    return re.split(r"[^a-z0-9]+", text.lower())


def count_terms(doc, term_length=1, common_words=set()):
    counts = {}
    for win_len in range(1, term_length + 1):
        for i in range(len(doc) + 1 - win_len):
            if not any(
                map(lambda word: word in common_words, doc[i : i + win_len])
            ):
                term = " ".join(doc[i : i + win_len])
                if  len(term) > 0 and not term.isspace():
                    counts[term] = counts.get(term, 0) + 1
    return counts


def process_doc(doc_fields, term_length=1, common_words=set()):
    if doc_fields["title"] and doc_fields["content"]:
        title_counts = count_terms(
            clean_text(doc_fields["title"]), term_length, common_words
        )
        content_counts = count_terms(
            clean_text(doc_fields["content"]), term_length, common_words
        )
        return {
            term: title_counts.get(term, 0) + content_counts.get(term, 0)
            for term in list(title_counts.keys()) + list(content_counts.keys())
        }
    else:
        return {}


def process_docs(obj, term_length=1, common_words=set()):
    doc_counts = [
        process_doc(doc["fields"], term_length, common_words) for doc in obj
    ]
    terms = {}

    # Sum counts
    for counts in doc_counts:
        total_count = sum([count for count in counts.values()])
        for (term, count) in counts.items():
            if term in terms:
                terms[term]["count"] = terms[term]["count"] + count
            else:
                terms[term] = {"term": term, "count": count}

    # Find number of documents containing the term
    for term in terms.keys():
        terms[term]["docs"] = sum(
            [1 if term in doc else 0 for doc in doc_counts]
        )

    return terms


def main():
    if len(sys.argv) == 3:
        write_json_file(process_docs(read_json_file(sys.argv[1])), sys.argv[2])
    elif len(sys.argv) == 4:
        write_json_file(
            process_docs(read_json_file(sys.argv[1]), int(sys.argv[3])),
            sys.argv[2],
        )
    elif len(sys.argv) == 5:
        write_json_file(
            process_docs(
                read_json_file(sys.argv[1]),
                int(sys.argv[3]),
                read_common_words(sys.argv[4]),
            ),
            sys.argv[2],
        )
    else:
        print(
            "Wrong number of arguments:",
            "python3",
            "count_terms.py",
            "infile.json",
            "outfile.json",
            "[number_of_words_in_term [common_words.txt]]",
        )


if __name__ == "__main__":
    main()

